# --- Script: Study 1 - Simulation Visualization (Figure 3) ---
# This script loads the results generated by the simulation study
# and creates a faceted scatterplot showing how the posterior median
# converges towards the true effect size across different sample sizes,
# prior locations, and prior scales.

# Load required libraries
library(ggplot2) # Core plotting engine
library(easystats) # Provides data_read() and theme_modern() functions
library(rstanarm) # Loaded for consistency with the modeling environment

