# --- Section: Data Preparation ---

# Read the saved simulation results using the easystats data_read() function
result <- data_read("Example1/Study 1 - Simulations.rds")

# Convert the 'Scale' variable into a factor and assign descriptive labels.
# This ensures that the facets in the final plot have clean, readable titles
# and are ordered correctly (from ultranarrow to wide).
result$Scale <- factor(
  result$Scale,
  labels = c(
    "ultranarrow prior scale",
    "narrow prior scale",
    "medium prior scale",
    "wide prior scale"
  )
)

# Explicitly set the factor levels (acts as a safety measure to guarantee order)
levels(result$Scale) <- c(
  "ultranarrow prior scale",
  "narrow prior scale",
  "medium prior scale",
  "wide prior scale"
)


# --- Section: Building the Main Plot ---

# Initialize the ggplot object
# x-axis: Sample Size (treated as categories/factors to create distinct columns)
# y-axis: The estimated Posterior Median from each simulation run
# color: The Prior Location used for that specific simulation
p <- ggplot(
  result,
  aes(x = as.factor(N), y = Median, color = as.factor(Location))
) +

  # Add a solid reference line representing the "True Effect" (0.3)
  geom_hline(yintercept = 0.3, color = "#5a5a5a", linewidth = 0.6) +

  # Plot individual simulation results as points.
  # Alpha (0.04) makes points highly transparent so density can be seen where
  # points overlap.
  # jitterdodge separates the overlapping points horizontally to prevent a
  # massive visual blob.
  geom_point(
    alpha = 0.04,
    fill = NA,
    size = 0.9,
    position = position_jitterdodge(dodge.width = 0.4, jitter.width = 0.2)
  ) +

  # Create a separate sub-plot (facet) for each Prior Scale
  facet_wrap(~Scale) +

  # Apply a clean, publication-ready theme from the easystats package
  theme_modern(show.ticks = TRUE) +
  theme(strip.text = element_text(size = 12, face = "plain")) +

  # Use a colorblind-friendly palette (Okabe-Ito) to distinguish the 5 prior
  # locations
  scale_color_manual(
    values = unname(see::okabeito_colors(c(
      "purple",
      "blue",
      "green",
      "amber",
      "red"
    )))
  ) +

  # Format the x-axis to only show labels at intervals of 50 (to prevent text
  # overlapping)
  scale_x_discrete(breaks = seq(0, 200, 50), labels = seq(0, 200, 50)) +

  # Adjust legend formatting:
  # - reverse = TRUE ensures the legend order matches the visual stacking of the
  #   points
  # - override.aes makes the legend points fully opaque (alpha = 1) instead of
  #   0.04
  guides(
    colour = guide_legend(reverse = TRUE, override.aes = list(alpha = 1))
  ) +

  # Define axis and legend labels
  labs(
    # title = "Posterior Median by Sample Size, Prior Location and Prior Scale",
    # subtitle = "for True Effect of 0.3",
    y = "Posterior Median",
    x = "Sample Size",
    colour = "Prior Location"
  ) +

  # Restrict the y-axis to the relevant range and define tick marks
  scale_y_continuous(limits = c(-0.3, 0.6), breaks = seq(-0.3, 0.6, 0.3))


# --- Section: Export Final Plot ---

# Save the complete figure as a high-resolution TIFF for publication
ggsave(
  "Figure 3.tiff",
  plot = p,
  device = "tiff",
  scale = 1.2,
  compress = "lzw", # Lossless compression standard for print journals
  width = 17,
  height = 14,
  unit = "cm",
  dpi = 600 # 600 dots-per-inch ensures crisp print quality
)
